<?php
require_once __DIR__ . '/includes/db_connection.php'; require_once __DIR__ . '/includes/functions.php'; require_once __DIR__ . '/includes/master_data.php';
startSecureSession(); requireLogin(); $conn=getDBConnection(); ensurePODSchema($conn); $note=trim($_GET['note']??''); $d=null; $pods=[];
if($note!==''){$like='%'.$note.'%';$sql="SELECT c.*, o.city_name origin_city, de.city_name destination_city, bt.type_name booking_type, tt.type_name truck_type FROM consignments c LEFT JOIN cities o ON o.id=c.origin_city_id LEFT JOIN cities de ON de.id=c.destination_city_id LEFT JOIN booking_types bt ON bt.id=c.booking_type_id LEFT JOIN truck_types tt ON tt.id=c.truck_type_id WHERE c.consignment_note LIKE ? OR c.billing_party_name LIKE ? OR c.consignor_name LIKE ? OR c.consignee_name LIKE ? OR c.billing_phone LIKE ? OR c.booking_date LIKE ? ORDER BY c.consignment_note = ? DESC, c.booking_date DESC LIMIT 1";$stmt=$conn->prepare($sql);$stmt->bind_param('sssssss',$like,$like,$like,$like,$like,$like,$note);$stmt->execute();$d=$stmt->get_result()->fetch_assoc();$stmt->close();if($d){$s=$conn->prepare('SELECT id,original_name,uploaded_at FROM pod_files WHERE consignment_id=? ORDER BY uploaded_at DESC');$s->bind_param('i',$d['id']);$s->execute();$pods=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}}
$stages=['Shipment Booked','Connecting to Next Destination','In Transit','Out for Delivery','Delivered'];$map=['In Transit'=>3,'Connecting to Next Destination'=>2,'Out for Delivery'=>4,'Delivered'=>5,'Hold'=>3,'Return'=>3];$active=$d?$map[$d['docket_tracking_status']]??1:1;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars(appBrandTitle('Docket Tracking')) ?></title><link rel="stylesheet" href="css/style.css"><style>.track-page{max-width:1100px;margin:16px auto}.track-search{display:flex;gap:8px;margin:12px 0}.track-card{background:#fff;border:1px solid #d8dee8;border-radius:6px;padding:14px}.track-banner{background:#ece6f4;padding:14px;border-radius:4px}.track-steps{display:flex;justify-content:space-between;position:relative;margin:14px 28px 4px}.track-steps:before{content:'';position:absolute;top:21px;left:9%;right:9%;height:3px;background:#6b7280}.track-step{z-index:1;text-align:center;width:20%;font-weight:700;color:#a0a7b0}.track-dot{width:44px;height:44px;margin:auto auto 8px;border-radius:50%;background:#b8bec6;color:#fff;display:flex;align-items:center;justify-content:center;font-size:1rem}.track-step.active{color:#2c3e50}.track-step.active .track-dot{background:#4caf50;border:3px solid #34495e}.detail-grid{display:grid;grid-template-columns:165px 1fr 125px 1fr;border:1px solid #d7dce1;margin-top:15px}.detail-grid>*{padding:9px;border-right:1px solid #d7dce1;border-bottom:1px solid #d7dce1}.detail-grid b{background:#f8f9fa}.tab-title{border-bottom:2px solid #2471a3;padding:8px 12px;display:inline-block;font-weight:700}.pod-links a{display:block;margin:5px 0}@media(max-width:700px){.detail-grid{grid-template-columns:120px 1fr}.detail-grid>*:nth-child(4n+3){grid-column:1}.track-step{font-size:.58rem}.track-steps{margin:14px 0}}</style></head><body><div class="app-shell"><aside class="app-sidebar"><?php renderAppBrand(); ?><nav class="sidebar-nav"><?php renderSidebarNav(); ?></nav><?php renderSidebarFooter(); ?></aside><div class="app-main"><?php renderAppHeader('Shipment Tracking', '🚛'); ?><main class="app-body"><div class="track-page"><form class="track-search"><input class="form-control" name="note" value="<?=htmlspecialchars($note)?>" placeholder="Enter consignment / LR number" required><button class="btn btn-primary">Track</button></form><?php if($note!==''&&!$d): ?><div class="alert alert-warning">Docket not found.</div><?php endif;?><?php if($d): ?><div class="track-card"><div class="track-banner"><b>Tracking ID: <?=htmlspecialchars($d['consignment_note'])?></b><div class="track-steps"><?php foreach($stages as $i=>$stage):$n=$i+1;?><div class="track-step <?=$n<=$active?'active':''?>"><div class="track-dot"><?=$n?></div><?=$stage?></div><?php endforeach;?></div></div><div class="tab-title">Shipment Details</div><div class="detail-grid"><b>Client</b><span><?=htmlspecialchars($d['billing_party_name'])?></span><b>Trans. Type</b><span><?=htmlspecialchars($d['booking_type']??'Forward')?></span><b>LR No.</b><span><?=htmlspecialchars($d['consignment_note'])?></span><b>Trans. Mode</b><span><?=htmlspecialchars($d['truck_type']??'Surface')?></span><b>LR Date</b><span><?=htmlspecialchars($d['booking_date'])?></span><b>No. Of Pcs</b><span><?=htmlspecialchars($d['no_of_pieces'])?></span><b>Weight (KG)</b><span><?=htmlspecialchars($d['charged_weight'])?> KG</span><b>Origin</b><span><?=htmlspecialchars($d['origin_city']??'')?></span><b>Delivery Date</b><span><?=htmlspecialchars($d['delivery_date']??'Not delivered')?></span><b>Destination</b><span><?=htmlspecialchars($d['destination_city']??'')?></span><b>Consignor</b><span><?=htmlspecialchars($d['consignor_name'])?><br><?=nl2br(htmlspecialchars($d['consignor_address']??''))?></span><b>Consignee</b><span><?=htmlspecialchars($d['consignee_name'])?><br><?=nl2br(htmlspecialchars($d['consignee_address']??''))?></span></div><div class="tab-title" style="margin-top:15px">POD Scan</div><div class="pod-links"><?php foreach($pods as $p):?><a target="_blank" href="api/download_pod.php?id=<?=$p['id']?>">📎 <?=htmlspecialchars($p['original_name'])?> <small>(<?=htmlspecialchars($p['uploaded_at'])?>)</small></a><?php endforeach;?><?php if(!$pods):?>No POD uploaded yet.<?php endif;?></div></div><?php endif;?></div></main></div></div></body></html>
